import type { ServiceConfig } from "../../config.js";
import type { Driver, DriverDataset, Location } from "../drivers/types.js";
import type { Ride } from "./types.js";

const earthRadiusMeters = 6_371_000;

export function distanceMeters(from: Location, to: Location): number {
  const radians = (degrees: number) => degrees * Math.PI / 180;
  const lat1 = radians(from.lat);
  const lat2 = radians(to.lat);
  const deltaLat = lat2 - lat1;
  const deltaLng = radians(to.lng - from.lng);
  const a = Math.min(1, Math.sin(deltaLat / 2) ** 2
    + Math.cos(lat1) * Math.cos(lat2) * Math.sin(deltaLng / 2) ** 2);
  return Math.round(earthRadiusMeters * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a)));
}

export interface Candidate {
  driver: Driver;
  distance_meters: number;
  pickup_eta_seconds: number;
}

interface EvaluatedCandidate {
  driver_id: string;
  eligible: boolean;
  reasons: string[];
  distance_meters: number | null;
  pickup_eta_seconds: number | null;
}

function evaluate(
  driver: Driver,
  ride: Ride,
  dataset: DriverDataset,
  config: ServiceConfig,
  strategy: string,
  isReserved: (driverId: string) => boolean,
): { candidate?: Candidate; result: EvaluatedCandidate } {
  const reasons: string[] = [];
  const distance = distanceMeters(driver.location, ride.pickup);
  let eta = 0;
  if (driver.status === "offline") reasons.push("offline");
  if (driver.vehicle_type !== ride.vehicle_type) reasons.push("vehicle_type_mismatch");
  const ageSeconds = Math.round((dataset.snapshotTime - Date.parse(driver.last_location_update)) / 1000);
  if (ageSeconds > config.location_max_age_seconds) reasons.push("location_too_old");
  if (driver.status === "on_trip") {
    if (strategy !== "fastest_eta") reasons.push("strategy_requires_available_driver");
    if (!config.allow_on_trip_drivers) reasons.push("on_trip_drivers_disabled");
    const trip = driver.current_trip;
    if (!trip || Math.round(trip.eta_to_dropoff_seconds) > config.max_remaining_trip_seconds) {
      reasons.push("trip_exceeds_max_remaining_time");
    } else {
      const onwardDistance = distanceMeters(trip.dropoff, ride.pickup);
      const onwardTime = Math.round(onwardDistance * config.route_factor / (config.avg_speed_kmh * 1000 / 3600));
      eta = Math.round(trip.eta_to_dropoff_seconds) + onwardTime;
    }
  } else {
    eta = Math.round(distance * config.route_factor / (config.avg_speed_kmh * 1000 / 3600));
  }
  if (driver.status !== "available" && driver.status !== "on_trip") reasons.push("unavailable");
  if (isReserved(driver.id)) reasons.push("driver_has_open_offer_or_accepted_ride");
  if (ride.triedDriverIds.has(driver.id)) reasons.push("already_offered_this_ride");
  if (!reasons.includes("trip_exceeds_max_remaining_time") && eta > config.max_pickup_eta_seconds) {
    reasons.push("pickup_eta_exceeds_limit");
  }
  const eligible = reasons.length === 0;
  return {
    candidate: eligible ? { driver, distance_meters: distance, pickup_eta_seconds: eta } : undefined,
    result: {
      driver_id: driver.id,
      eligible,
      reasons,
      distance_meters: distance,
      pickup_eta_seconds: Number.isFinite(eta) ? eta : null,
    },
  };
}

export interface CandidateList {
  ranked: Candidate[];
  evaluated: EvaluatedCandidate[];
}

type Strategy = (left: Candidate, right: Candidate) => number;

const strategies: Record<string, Strategy> = {
  nearest: (left, right) =>
    left.distance_meters - right.distance_meters
      || left.pickup_eta_seconds - right.pickup_eta_seconds
      || compareIds(left.driver.id, right.driver.id),
  fastest_eta: (left, right) =>
    left.pickup_eta_seconds - right.pickup_eta_seconds
      || compareIds(left.driver.id, right.driver.id),
};

function compareIds(left: string, right: string): number {
  return left < right ? -1 : left > right ? 1 : 0;
}

export function assertSupportedStrategy(strategy: string): void {
  if (!strategies[strategy]) throw new Error(`Unsupported matching strategy: ${strategy}`);
}

export function rankCandidates(
  ride: Ride,
  dataset: DriverDataset,
  config: ServiceConfig,
  isReserved: (driverId: string) => boolean,
): CandidateList {
  const strategy = strategies[config.strategy];
  if (!strategy) throw new Error(`Unsupported matching strategy: ${config.strategy}`);
  const ranked: Candidate[] = [];
  const evaluated: EvaluatedCandidate[] = [];
  for (const driver of dataset.drivers) {
    const result = evaluate(driver, ride, dataset, config, config.strategy, isReserved);
    evaluated.push(result.result);
    if (result.candidate) ranked.push(result.candidate);
  }
  ranked.sort(strategy);
  return { ranked, evaluated };
}
import { randomUUID } from "node:crypto";
import type { ServiceConfig } from "../../config.js";
import type { DriverDataset } from "../drivers/types.js";
import { rankCandidates, type CandidateList } from "./matching.js";
import type { CreateRideInput, Offer, Ride } from "./types.js";

interface Reservation {
  offerId: string;
  rideId: string;
  accepted: boolean;
}

interface OfferWaiter {
  resolve: () => void;
  timer: NodeJS.Timeout;
}

export class RideService {
  private readonly rides = new Map<string, Ride>();
  private readonly reservations = new Map<string, Reservation>();
  private readonly offerWaiters = new Map<string, OfferWaiter>();
  private readonly offerEtas = new Map<string, number>();

  constructor(
    private readonly dataset: DriverDataset,
    private readonly config: ServiceConfig,
  ) {}

  createRide(input: CreateRideInput): Ride {
    const ride: Ride = {
      ride_id: `ride_${randomUUID()}`,
      ...input,
      status: "matching",
      offers: [],
      triedDriverIds: new Set(),
    };
    this.rides.set(ride.ride_id, ride);
    setImmediate(() => {
      void this.dispatch(ride).catch((error: unknown) => {
        console.error(`Ride dispatch failed for ${ride.ride_id}:`, error);
      });
    });
    return ride;
  }

  getRide(rideId: string): Ride | undefined {
    const ride = this.rides.get(rideId);
    if (ride) this.expireOpenOffer(ride);
    return ride;
  }

  cancelRide(rideId: string): Ride {
    const ride = this.requireRide(rideId);
    if (ride.status === "accepted") throw new ServiceError(409, "ride_already_accepted", "An accepted ride cannot be cancelled");
    if (ride.status === "cancelled") return ride;
    ride.status = "cancelled";
    const offer = ride.offers.find((item) => item.status === "open");
    if (offer) this.closeOffer(offer, "withdrawn");
    return ride;
  }

  getDriverOffers(driverId: string): { driver_id: string; offers: Offer[] } {
    const driver = this.dataset.drivers.find((item) => item.id === driverId);
    if (!driver) throw new ServiceError(404, "driver_not_found", "Driver not found");
    const reservation = this.reservations.get(driverId);
    if (!reservation || reservation.accepted) return { driver_id: driverId, offers: [] };
    const ride = this.requireRide(reservation.rideId);
    this.expireOpenOffer(ride);
    const openOffer = ride.offers.find((item) => item.offer_id === reservation.offerId && item.status === "open");
    return { driver_id: driverId, offers: openOffer ? [openOffer] : [] };
  }

  acceptOffer(offerId: string): { offer_id: string; ride_id: string; status: "accepted" } {
    const { ride, offer } = this.requireOffer(offerId);
    this.expireOpenOffer(ride);
    if (offer.status === "accepted") return { offer_id: offer.offer_id, ride_id: ride.ride_id, status: "accepted" };
    if (ride.status === "cancelled") {
      throw new ServiceError(410, "offer_withdrawn", "This offer belongs to a cancelled ride");
    }
    if (offer.status === "timed_out") throw new ServiceError(410, "offer_expired", "This offer has expired");
    if (offer.status === "withdrawn") {
      throw new ServiceError(410, "offer_withdrawn", "This offer was withdrawn because the ride was cancelled");
    }
    if (offer.status !== "open") throw new ServiceError(409, "offer_not_open", `Offer is ${offer.status}`);
    if (ride.status !== "offered") throw new ServiceError(409, "ride_not_accepting_offers", "This ride is no longer accepting offers");

    offer.status = "accepted";
    ride.status = "accepted";
    ride.driver = this.dataset.drivers.find((driver) => driver.id === offer.driver_id);
    if (!ride.driver) throw new Error(`Driver ${offer.driver_id} disappeared from the dataset`);
    ride.pickup_eta_seconds = this.offerEtas.get(offer.offer_id);
    this.reservations.set(offer.driver_id, { offerId: offer.offer_id, rideId: ride.ride_id, accepted: true });
    this.resolveOffer(offer.offer_id);
    return { offer_id: offer.offer_id, ride_id: ride.ride_id, status: "accepted" };
  }

  declineOffer(offerId: string): { offer_id: string; ride_id: string; status: "declined" } {
    const { ride, offer } = this.requireOffer(offerId);
    this.expireOpenOffer(ride);
    if (offer.status !== "open") {
      throw new ServiceError(offer.status === "timed_out" ? 410 : 409, "offer_not_open", `Offer is ${offer.status}`);
    }
    this.closeOffer(offer, "declined");
    return { offer_id: offer.offer_id, ride_id: ride.ride_id, status: "declined" };
  }

  getCandidates(rideId: string): CandidateList & {
    excluded_records: DriverDataset["excludedRecords"];
  } {
    const ride = this.requireRide(rideId);
    return {
      ...rankCandidates(ride, this.dataset, this.config, (driverId) => this.reservations.has(driverId)),
      excluded_records: this.dataset.excludedRecords,
    };
  }

  private async dispatch(ride: Ride): Promise<void> {
    while (ride.status === "matching" || ride.status === "offered") {
      if (ride.offers.length >= this.config.max_offer_attempts) {
        ride.status = "no_driver_found";
        return;
      }
      const next = rankCandidates(ride, this.dataset, this.config, (driverId) => this.reservations.has(driverId)).ranked[0];
      if (!next) {
        ride.status = "no_driver_found";
        return;
      }
      const now = Date.now();
      const offer: Offer = {
        offer_id: `ofr_${randomUUID()}`,
        driver_id: next.driver.id,
        status: "open",
        created_at: new Date(now).toISOString(),
        expires_at: new Date(now + this.config.offer_timeout_seconds * 1000).toISOString(),
      };
      this.offerEtas.set(offer.offer_id, next.pickup_eta_seconds);
      ride.offers.push(offer);
      ride.triedDriverIds.add(next.driver.id);
      ride.status = "offered";
      this.reservations.set(next.driver.id, { offerId: offer.offer_id, rideId: ride.ride_id, accepted: false });
      await new Promise<void>((resolve) => {
        const timer = setTimeout(() => {
          if (offer.status === "open") this.closeOffer(offer, "timed_out");
          resolve();
        }, this.config.offer_timeout_seconds * 1000);
        this.offerWaiters.set(offer.offer_id, { resolve, timer });
      });
      if (ride.status !== "offered") return;
      ride.status = "matching";
    }
  }

  private closeOffer(offer: Offer, status: "declined" | "timed_out" | "withdrawn"): void {
    if (offer.status !== "open") return;
    offer.status = status;
    const reservation = this.reservations.get(offer.driver_id);
    if (reservation?.offerId === offer.offer_id) this.reservations.delete(offer.driver_id);
    this.resolveOffer(offer.offer_id);
  }

  private expireOpenOffer(ride: Ride): void {
    const offer = ride.offers.find((item) => item.status === "open");
    if (offer && Date.now() >= Date.parse(offer.expires_at)) this.closeOffer(offer, "timed_out");
  }

  private resolveOffer(offerId: string): void {
    const waiter = this.offerWaiters.get(offerId);
    if (!waiter) return;
    clearTimeout(waiter.timer);
    this.offerWaiters.delete(offerId);
    waiter.resolve();
  }

  private requireRide(rideId: string): Ride {
    const ride = this.rides.get(rideId);
    if (!ride) throw new ServiceError(404, "ride_not_found", "Ride not found");
    return ride;
  }

  private requireOffer(offerId: string): { ride: Ride; offer: Offer } {
    for (const ride of this.rides.values()) {
      const offer = ride.offers.find((item) => item.offer_id === offerId);
      if (offer) return { ride, offer };
    }
    throw new ServiceError(404, "offer_not_found", "Offer not found");
  }
}

export class ServiceError extends Error {
  constructor(
    readonly statusCode: number,
    readonly code: string,
    message: string,
  ) {
    super(message);
  }
}

import express, { type ErrorRequestHandler, type Request, type Response } from "express";
import type { ServiceConfig } from "./config.js";
import type { DriverDataset, Location, VehicleType } from "./resources/drivers/types.js";
import { assertSupportedStrategy } from "./resources/rides/matching.js";
import { RideService, ServiceError } from "./resources/rides/service.js";
import type { Ride } from "./resources/rides/types.js";

const vehicleTypes = new Set<VehicleType>(["economy", "comfort", "xl"]);

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isLocation(value: unknown): value is Location {
  return isObject(value)
    && typeof value.lat === "number" && Number.isFinite(value.lat) && value.lat >= -90 && value.lat <= 90
    && typeof value.lng === "number" && Number.isFinite(value.lng) && value.lng >= -180 && value.lng <= 180;
}

function routeParam(value: string | string[]): string {
  return Array.isArray(value) ? value[0] ?? "" : value;
}

function parseRideInput(value: unknown) {
  if (!isObject(value)) throw new ServiceError(400, "invalid_request", "Request body must be an object");
  if (typeof value.rider_id !== "string" || !value.rider_id.trim()) {
    throw new ServiceError(400, "invalid_request", "rider_id must be a non-empty string");
  }
  if (!isLocation(value.pickup) || !isLocation(value.dropoff)) {
    throw new ServiceError(400, "invalid_request", "pickup and dropoff must contain valid lat and lng coordinates");
  }
  if (typeof value.vehicle_type !== "string" || !vehicleTypes.has(value.vehicle_type as VehicleType)) {
    throw new ServiceError(400, "invalid_request", "vehicle_type must be economy, comfort, or xl");
  }
  return {
    rider_id: value.rider_id.trim(),
    pickup: value.pickup,
    dropoff: value.dropoff,
    vehicle_type: value.vehicle_type as VehicleType,
  };
}

function serializeRide(ride: Ride) {
  return {
    ride_id: ride.ride_id,
    status: ride.status,
    ...(ride.driver ? {
      driver: {
        id: ride.driver.id,
        name: ride.driver.name,
        vehicle_type: ride.driver.vehicle_type,
        rating: ride.driver.rating,
      },
      pickup_eta_seconds: ride.pickup_eta_seconds,
    } : {}),
    offers: ride.offers.map(({ offer_id, driver_id, status, created_at, expires_at }) => ({
      offer_id,
      driver_id,
      status,
      created_at,
      expires_at,
    })),
  };
}

export function createApp(dataset: DriverDataset, config: ServiceConfig) {
  assertSupportedStrategy(config.strategy);
  const app = express();
  const rides = new RideService(dataset, config);
  app.use(express.json());

  app.post("/rides", (request: Request, response: Response) => {
    const ride = rides.createRide(parseRideInput(request.body));
    response.status(202).json({ ride_id: ride.ride_id, status: ride.status });
  });

  app.get("/rides/:ride_id/candidates", (request: Request, response: Response) => {
    response.json(rides.getCandidates(routeParam(request.params.ride_id)));
  });

  app.get("/rides/:ride_id", (request: Request, response: Response) => {
    response.json(serializeRide(requireRide(rides, routeParam(request.params.ride_id))));
  });

  app.post("/rides/:ride_id/cancel", (request: Request, response: Response) => {
    response.json(serializeRide(rides.cancelRide(routeParam(request.params.ride_id))));
  });

  app.get("/drivers/:driver_id/offers", (request: Request, response: Response) => {
    response.json(rides.getDriverOffers(routeParam(request.params.driver_id)));
  });

  app.post("/offers/:offer_id/accept", (request: Request, response: Response) => {
    response.json(rides.acceptOffer(routeParam(request.params.offer_id)));
  });

  app.post("/offers/:offer_id/decline", (request: Request, response: Response) => {
    response.json(rides.declineOffer(routeParam(request.params.offer_id)));
  });

  const errorHandler: ErrorRequestHandler = (error: unknown, _request, response, _next) => {
    if (error instanceof ServiceError) {
      response.status(error.statusCode).json({ error: { code: error.code, message: error.message } });
      return;
    }
    if (isObject(error) && error.type === "entity.parse.failed") {
      response.status(400).json({ error: { code: "invalid_json", message: "Request body is not valid JSON" } });
      return;
    }
    console.error("Unhandled request error:", error);
    response.status(500).json({ error: { code: "internal_error", message: "An internal error occurred" } });
  };
  app.use(errorHandler);
  return app;
}

function requireRide(service: RideService, rideId: string): Ride {
  const ride = service.getRide(rideId);
  if (!ride) throw new ServiceError(404, "ride_not_found", "Ride not found");
  return ride;
}
import { readFile } from "node:fs/promises";
import type { Driver, DriverDataset, DriverStatus, Location, VehicleType } from "./types.js";

const vehicleTypes = new Set<VehicleType>(["economy", "comfort", "xl"]);
const statuses = new Set<DriverStatus>(["available", "on_trip", "offline"]);

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isLocation(value: unknown): value is Location {
  if (!isObject(value)) return false;
  return typeof value.lat === "number" && Number.isFinite(value.lat) && value.lat >= -90 && value.lat <= 90
    && typeof value.lng === "number" && Number.isFinite(value.lng) && value.lng >= -180 && value.lng <= 180;
}

function parseDriver(value: unknown, snapshotTime: number): { driver?: Driver; reason?: string; id: string | null } {
  const id = isObject(value) && typeof value.id === "string" ? value.id : null;
  if (!isObject(value)) return { id, reason: "record is not an object" };
  if (!id || typeof value.name !== "string" || !value.name) return { id, reason: "missing id or name" };
  if (typeof value.status !== "string" || !statuses.has(value.status as DriverStatus)) {
    return { id, reason: "invalid status" };
  }
  if (!isLocation(value.location)) return { id, reason: "invalid location" };
  if (typeof value.vehicle_type !== "string" || !vehicleTypes.has(value.vehicle_type as VehicleType)) {
    return { id, reason: "invalid vehicle_type" };
  }
  if (typeof value.speed_kmh !== "number" || !Number.isFinite(value.speed_kmh) || value.speed_kmh < 0) {
    return { id, reason: "invalid speed_kmh" };
  }
  if (value.heading_deg !== null && (typeof value.heading_deg !== "number"
    || !Number.isFinite(value.heading_deg) || value.heading_deg < 0 || value.heading_deg >= 360)) {
    return { id, reason: "invalid heading_deg" };
  }
  if (typeof value.rating !== "number" || !Number.isFinite(value.rating) || value.rating < 1 || value.rating > 5) {
    return { id, reason: "invalid rating" };
  }
  if (typeof value.acceptance_rate !== "number" || !Number.isFinite(value.acceptance_rate)
    || value.acceptance_rate < 0 || value.acceptance_rate > 1) {
    return { id, reason: "invalid acceptance_rate" };
  }
  const updateTime = typeof value.last_location_update === "string" ? Date.parse(value.last_location_update) : NaN;
  if (!Number.isFinite(updateTime) || updateTime > snapshotTime) {
    return { id, reason: "invalid last_location_update" };
  }

  let currentTrip: Driver["current_trip"] = null;
  if (value.status === "on_trip") {
    if (!isObject(value.current_trip) || !isLocation(value.current_trip.dropoff)
      || typeof value.current_trip.eta_to_dropoff_seconds !== "number"
      || !Number.isFinite(value.current_trip.eta_to_dropoff_seconds)
      || value.current_trip.eta_to_dropoff_seconds < 0) {
      return { id, reason: "invalid current_trip" };
    }
    currentTrip = {
      dropoff: value.current_trip.dropoff,
      eta_to_dropoff_seconds: value.current_trip.eta_to_dropoff_seconds,
    };
  } else if (value.current_trip !== null) {
    return { id, reason: "non-trip driver has a current_trip" };
  }

  return {
    id,
    driver: {
      id,
      name: value.name,
      status: value.status as DriverStatus,
      location: value.location,
      vehicle_type: value.vehicle_type as VehicleType,
      rating: value.rating,
      last_location_update: value.last_location_update as string,
      current_trip: currentTrip,
    },
  };
}

export async function loadDrivers(path = "drivers.json"): Promise<DriverDataset> {
  const parsed: unknown = JSON.parse(await readFile(path, "utf8"));
  if (!isObject(parsed) || !Array.isArray(parsed.drivers) || typeof parsed.snapshot_time !== "string") {
    throw new Error("drivers.json must contain snapshot_time and a drivers array");
  }
  const snapshotTime = Date.parse(parsed.snapshot_time);
  if (!Number.isFinite(snapshotTime)) throw new Error("drivers.json snapshot_time is invalid");

  const excludedRecords: DriverDataset["excludedRecords"] = [];
  const valid: Driver[] = [];
  for (const record of parsed.drivers) {
    const result = parseDriver(record, snapshotTime);
    if (result.driver) valid.push(result.driver);
    else excludedRecords.push({ id: result.id, reason: result.reason ?? "invalid record" });
  }

  const newestById = new Map<string, Driver>();
  for (const driver of valid) {
    const existing = newestById.get(driver.id);
    if (!existing) {
      newestById.set(driver.id, driver);
      continue;
    }
    if (Date.parse(driver.last_location_update) > Date.parse(existing.last_location_update)) {
      excludedRecords.push({ id: existing.id, reason: "superseded by a newer duplicate" });
      newestById.set(driver.id, driver);
    } else {
      excludedRecords.push({ id: driver.id, reason: "superseded by a newer duplicate" });
    }
  }
  return { snapshotTime, drivers: [...newestById.values()], excludedRecords };
}
import { readFile } from "node:fs/promises";

export interface ServiceConfig {
  strategy: string;
  avg_speed_kmh: number;
  route_factor: number;
  max_pickup_eta_seconds: number;
  location_max_age_seconds: number;
  allow_on_trip_drivers: boolean;
  max_remaining_trip_seconds: number;
  offer_timeout_seconds: number;
  max_offer_attempts: number;
}

const isPositiveNumber = (value: unknown): value is number =>
  typeof value === "number" && Number.isFinite(value) && value > 0;

export function validateConfig(value: unknown): ServiceConfig {
  if (!value || typeof value !== "object") throw new Error("Configuration must be a JSON object");
  const config = value as Record<string, unknown>;
  const numericKeys = [
    "avg_speed_kmh",
    "route_factor",
    "max_pickup_eta_seconds",
    "location_max_age_seconds",
    "max_remaining_trip_seconds",
    "offer_timeout_seconds",
    "max_offer_attempts",
  ] as const;
  for (const key of numericKeys) {
    if (!isPositiveNumber(config[key])) throw new Error(`Configuration ${key} must be a positive number`);
  }
  if (!Number.isInteger(config.max_offer_attempts)) {
    throw new Error("Configuration max_offer_attempts must be an integer");
  }
  if (typeof config.strategy !== "string" || !config.strategy) {
    throw new Error("Configuration strategy must be a non-empty string");
  }
  if (typeof config.allow_on_trip_drivers !== "boolean") {
    throw new Error("Configuration allow_on_trip_drivers must be a boolean");
  }
  return config as unknown as ServiceConfig;
}

export async function loadConfig(path = "config.example.json"): Promise<ServiceConfig> {
  return validateConfig(JSON.parse(await readFile(path, "utf8")));
